@pytest.fixture
def queue_store():
    return InMemoryTaskQueue()

def test_add_task_returns_record_with_id(queue_store):
    task = queue_store.add_task("integration", "test prompt")
    assert task.id.startswith("task-")
    assert task.status == TaskStatus.PENDING

def test_coordination_status_reflects_last_added(queue_store):
    task = queue_store.add_task("integration", "test")
    snap = queue_store.coordination_status()
    assert snap.last_added_task_id == task.id
    assert snap.queue_revision > 0

def test_list_tasks_filter_by_id(queue_store):
    task = queue_store.add_task("integration", "test")
    result = queue_store.list_tasks(task_id=task.id)
    assert len(result) == 1 and result[0].id == task.id

def test_idempotent_add_same_prompt(queue_store):
    t1 = queue_store.add_task("integration", "same prompt")
    t2 = queue_store.add_task("integration", "same prompt")
    assert t1.id == t2.id
    assert queue_store.coordination_status().queue_revision == 1

